package com.codegym.dao;
import com.codegym.model.User; import java.sql.*; import java.util.*;
public class UserDAO implements IUserDAO {
 private static final String URL="jdbc:mysql://localhost:3306/user_management?useSSL=false&serverTimezone=UTC"; private static final String USER="root"; private static final String PASSWORD="";
 static { try { Class.forName("com.mysql.cj.jdbc.Driver"); } catch (ClassNotFoundException e) { throw new ExceptionInInitializerError(e); } }
 private Connection connect() throws SQLException { return DriverManager.getConnection(URL,USER,PASSWORD); }
 public List<User> selectUsers(String country,String sort)throws SQLException { String sql="SELECT id,name,email,country FROM users WHERE country LIKE ? ORDER BY name "+("desc".equalsIgnoreCase(sort)?"DESC":"ASC"); List<User> out=new ArrayList<>(); try(Connection c=connect();PreparedStatement p=c.prepareStatement(sql)){p.setString(1,"%"+(country==null?"":country.trim())+"%");try(ResultSet r=p.executeQuery()){while(r.next())out.add(new User(r.getInt("id"),r.getString("name"),r.getString("email"),r.getString("country")));}} return out; }
 public User findById(int id)throws SQLException { try(Connection c=connect();PreparedStatement p=c.prepareStatement("SELECT id,name,email,country FROM users WHERE id=?")){p.setInt(1,id);try(ResultSet r=p.executeQuery()){return r.next()?new User(r.getInt(1),r.getString(2),r.getString(3),r.getString(4)):null;}} }
 public void insert(User u)throws SQLException { try(Connection c=connect();PreparedStatement p=c.prepareStatement("INSERT INTO users(name,email,country) VALUES(?,?,?)")){setUser(p,u);p.executeUpdate();} }
 public void update(User u)throws SQLException { try(Connection c=connect();PreparedStatement p=c.prepareStatement("UPDATE users SET name=?,email=?,country=? WHERE id=?")){setUser(p,u);p.setInt(4,u.getId());p.executeUpdate();} }
 public void delete(int id)throws SQLException { try(Connection c=connect();PreparedStatement p=c.prepareStatement("DELETE FROM users WHERE id=?")){p.setInt(1,id);p.executeUpdate();} }
 private void setUser(PreparedStatement p,User u)throws SQLException {p.setString(1,u.getName());p.setString(2,u.getEmail());p.setString(3,u.getCountry());}
 public void addUserTransaction(User u,int[] permissionIds)throws SQLException { try(Connection c=connect()){c.setAutoCommit(false);try{int userId;try(PreparedStatement p=c.prepareStatement("INSERT INTO users(name,email,country) VALUES(?,?,?)",Statement.RETURN_GENERATED_KEYS)){setUser(p,u);p.executeUpdate();try(ResultSet r=p.getGeneratedKeys()){if(!r.next())throw new SQLException("Could not obtain generated user id");userId=r.getInt(1);}}if(permissionIds!=null){try(PreparedStatement p=c.prepareStatement("INSERT INTO user_permission(user_id,permission_id) VALUES(?,?)")){for(int permissionId:permissionIds){p.setInt(1,userId);p.setInt(2,permissionId);p.executeUpdate();}}}c.commit();}catch(SQLException e){try{c.rollback();}catch(SQLException rollback){e.addSuppressed(rollback);}throw e;}finally{try{c.setAutoCommit(true);}catch(SQLException ignored){}}} }
}
